<script setup lang="ts">
import {computed,defineAsyncComponent,nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import {api,can,productModules,basicOperations,operationAvailable,ifxTableAddress,ifxInternalSlot,session as getSession,type Session,type Configuration,type Channel,type Tank,type EventRow} from './api';
import type {Acquisition,Metric,LiveReading} from './api';
import TankGraphic from './TankGraphic.vue';
import {hasFrozenSurface} from './surfaceDisplay';
import TankConfigurationTransfer from './TankConfigurationTransfer.vue';
import UiIcon from './UiIcon.vue';
import BrandHeader from './BrandHeader.vue';
import CurrentReadings from './CurrentReadings.vue';
import CapacityTables from './CapacityTables.vue';
import PresentationSettings from './PresentationSettings.vue';
const TrendBoard=defineAsyncComponent(()=>import('./TrendBoard.vue'));
import AlarmEditor from './AlarmEditor.vue';
