import ControlsEditor from './ControlsEditor.vue';
import Accounts from './Accounts.vue';
import Authorization from './Authorization.vue';
import ReadOnlyIntegration from './ReadOnlyIntegration.vue';
import type {ProductPresentation,AuthorizationStatus} from './api';
import AlarmCenter from './AlarmCenter.vue';
import HistoryRecords from './HistoryRecords.vue';
import DataJobs from './DataJobs.vue';
import Snapshots from './Snapshots.vue';
import Schedules from './Schedules.vue';
import TankDetail from './TankDetailScreen.vue';
import PrintPreview from './PrintPreview.vue';
import {closePrintPreview} from './printPreview';
const WirelessTasks=__AVERAGE_DELIVERY__?defineAsyncComponent(()=>import('./WirelessTasks.vue')):null;
import type {AlarmSummary,AlarmSettings} from './api';
import {unit,displayMetric,qualityNames,converted,type Quantity} from './units';
import type {CapacitySummary} from './api';
const clone=<T,>(value:T):T=>JSON.parse(JSON.stringify(value));
const identity=ref<Session|null>(null),config=ref<Configuration|null>(null),events=ref<EventRow[]>([]),error=ref(''),message=ref(''),busy=ref(false),view=ref('overview'),unsaved=ref(false);
const login=ref(''),password=ref(''),displayName=ref(''),category=ref('all'),keyword=ref(''),actor=ref(''),filterTank=ref('all'),start=ref(''),end=ref(''),storage=ref<Record<string,unknown>|null>(null),details=ref<EventRow|null>(null);
const tankDetailScreen=ref<InstanceType<typeof TankDetail>|null>(null),trendFocusTank=ref<string>(),averageFocusTank=ref<string>();
const tankTab=ref('archive');
const tankEditorError=ref('');
const copyGroupSource=ref<string|null>(null);
const tankTabs=[['archive','仪表档案'],['binding','通讯绑定'],['capacity','罐容表'],['meter','计量参数'],['control','操作与温度'],['alarm','报警配置']];
const newIdentity=ref<{tag:string;code:string}|null>(null),identityError=ref('');
const sidebarCollapsed=ref(localStorage.getItem('level.sidebar.collapsed')==='true');
watch(sidebarCollapsed,v=>localStorage.setItem('level.sidebar.collapsed',String(v)));
function confirmNewIdentity(){const tag=newIdentity.value?.tag.trim()||'',code=newIdentity.value?.code.trim()||'';if(!tag||!code){identityError.value='请填写仪表位号和罐号';return}if(config.value?.tanks.some(t=>t.instrumentTag.toLowerCase()===tag.toLowerCase()||t.code.toLowerCase()===code.toLowerCase())){identityError.value='仪表位号或罐号已被使用，请核对';return}createTankDraft();if(tankDraft.value){tankDraft.value.instrumentTag=tag;tankDraft.value.code=code}newIdentity.value=null}

async function submitTank(event:Event){const form=event.currentTarget as HTMLFormElement;const invalid=form.querySelector<HTMLInputElement>('input:invalid,select:invalid,textarea:invalid');if(invalid){const pane=invalid.closest<HTMLElement>('[data-tank-tab]');if(pane)tankTab.value=pane.dataset.tankTab!;for(let p=invalid.parentElement;p;p=p.parentElement)if(p instanceof HTMLDetailsElement)p.open=true;await nextTick();invalid.focus();invalid.reportValidity();return}acceptTank()}
const basicViews=['tables','media','units','schedules'];
const basicTabs=[['tables','罐容表管理'],['media','介质与计量'],['units','显示单位'],['schedules','定时任务']];
const systemTab=ref('parameters'),persistedRetention=ref(12),retentionBackup=ref(''),retentionConfirmed=ref(false);
const backupChoices=ref<{id:string;createdAtUtc:string;state:string;kind:string}[]>([]);
async function loadBackups(){if(can('BackupManage')&&licensed.value)backupChoices.value=await api('/api/data-jobs')}

const presentation=ref<ProductPresentation>({branding:{softwareName:'液位管理系统',manufacturerName:'',manufacturerInformation:'',logoDataUrl:null,iconDataUrl:null},enabledModules:[]}),authorization=ref<AuthorizationStatus|null>(null);
const recoveryTank=ref(''),recoveryCycle=ref('Normal');
const recovery=ref<{requiresReview:boolean;message:string}|null>(null),recoveryReason=ref(''),recoveryConfirmed=ref(false);
const averageDelivered=computed(()=>__AVERAGE_DELIVERY__&&presentation.value.enabledModules.includes('average-temperature'));
const authorizationAt=ref(performance.now());
const licensed=computed(()=>!!authorization.value?.allowsLicensedActions&&(!authorization.value.expiresAtUtc||Date.parse(authorization.value.effectiveUtc)+Math.max(0,tick.value-authorizationAt.value)<Date.parse(authorization.value.expiresAtUtc)));
watch(licensed,allowed=>{if(!allowed){events.value=[];details.value=null}});
let authPoll=0;
async function refreshPresentation(){if(identity.value?.user){identity.value=await getSession();if(!can('HistoryRead')){events.value=[];details.value=null}}presentation.value=await api('/api/presentation');productModules.value=presentation.value.enabledModules;document.title=presentation.value.branding.softwareName;let icon=document.querySelector<HTMLLinkElement>('link[rel="icon"]');if(presentation.value.branding.iconDataUrl){if(!icon){icon=document.createElement('link');icon.rel='icon';document.head.appendChild(icon)}icon.href=presentation.value.branding.iconDataUrl}if(!averageDelivered.value&&view.value==='wireless')view.value='overview';if(identity.value?.user){authorization.value=await api('/api/authorization/status');authorizationAt.value=performance.now();recovery.value=await api('/api/storage/recovery')}}

const alarmSummary=ref<AlarmSummary|null>(null),alarmError=ref('');
let alarmPoll=0;
const groupFilter=ref('all'),mediumFilter=ref('all');
const overviewGroupKind=ref('all'),overviewSearch=ref(''),overviewStatus=ref('all');
function restoredOverviewView():'cards'|'list'{try{return localStorage.getItem('level.overview.view')==='list'?'list':'cards'}catch{return 'cards'}}
const overviewView=ref<'cards'|'list'>(restoredOverviewView());
type CardSize='compact'|'standard'|'large';
function restoredCardSize():CardSize{try{const size=localStorage.getItem('level.overview.card-size');return size==='compact'||size==='large'?size:'standard'}catch{return 'standard'}}
const overviewCardSize=ref<CardSize>(restoredCardSize());
watch(overviewCardSize,size=>{try{localStorage.setItem('level.overview.card-size',size)}catch{}});
const desktopBridge=(window as unknown as {chrome?:{webview?:{postMessage:(message:string)=>void}}}).chrome?.webview;
function showDownloads(){desktopBridge?.postMessage('open-downloads')}

function setOverviewView(mode:'cards'|'list'){overviewView.value=mode;try{localStorage.setItem('level.overview.view',mode)}catch{}if(mode==='cards'&&view.value==='list')void choose('overview')}
const overviewGroupOptions=computed(()=>(config.value?.groups||[]).filter(g=>overviewGroupKind.value==='all'||g.kind===overviewGroupKind.value));
watch(overviewGroupKind,()=>groupFilter.value='all');
watch(overviewGroupOptions,groups=>{if(groupFilter.value!=='all'&&!groups.some(g=>g.id===groupFilter.value))groupFilter.value='all'});
const overviewStatusOptions=[['all','全部储罐'],['attention','需关注'],['working','作业中'],['invalid','离线 / 无效']];
const capacitySummaries=ref<CapacitySummary[]>([]);
const acquisition=ref<Acquisition|null>(null),detailTank=ref(''),reportsOpen=ref(false),connectionIssue=ref(false),tick=ref(performance.now());
let pollTimer:ReturnType<typeof setInterval>|undefined,polling=false,lastPoll=performance.now();
const canOperate=computed(()=>can('InstrumentControl'));
const canConfigure=computed(()=>can('ConfigurationEdit'));
async function refreshAcquisition(){if(polling)return;polling=true;try{if(performance.now()-authPoll>3000){await refreshPresentation();authPoll=performance.now()}acquisition.value=await api<Acquisition>('/api/acquisition');lastPoll=performance.now();connectionIssue.value=false;if(config.value&&!unsaved.value&&acquisition.value.configurationRevision!==config.value.revision){config.value=await api<Configuration>('/api/config');persistedRetention.value=config.value.retentionMonths;if(!config.value.tanks.some(t=>t.id===detailTank.value&&!t.hidden))detailTank.value=config.value.tanks.find(t=>!t.hidden)?.id||''}if(performance.now()-alarmPoll>1500){const a=await api<{summary:AlarmSummary;error:string}>('/api/alarms/summary');alarmSummary.value=a.summary;alarmError.value=a.error;alarmPoll=performance.now()}}finally{polling=false}}
function reading(tankId:string){return acquisition.value?.readings.find(r=>r.tankId===tankId)}
function liveValid(r:LiveReading|undefined){if(!r||!acquisition.value?.running||!config.value||r.configurationRevision!==config.value.revision)return false;const serverNow=Date.parse(acquisition.value.serverAtUtc)+Math.max(0,tick.value-lastPoll);return serverNow>=Date.parse(r.receivedAtUtc)&&serverNow-Date.parse(r.receivedAtUtc)<=config.value.readingExpirySeconds*1000}
function metric(m:Metric|undefined,d=1){return m?.quality==='Good'&&m.value!==null?m.value.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d}):'—'}
function liveMetric(r:LiveReading|undefined,m:Metric|undefined,d=1){return liveValid(r)?metric(m,d):'—'}
async function startAcquisition(){await task(async()=>{acquisition.value=await api('/api/acquisition/start','POST',{});lastPoll=performance.now();message.value='已启动只读采集，未主动发送仪表控制。'})}
async function resetRecoveryGateway(){await task(async()=>{if(unsaved.value)throw Error('请先保存或重新载入待保存配置');await api('/api/storage/recovery-gateway-reset/'+recoveryTank.value,'POST',{configurationRevision:config.value?.revision,cycle:recoveryCycle.value,reason:recoveryReason.value,confirmed:recoveryConfirmed.value});message.value='已受理所选结果通道复位；清结果不停止浮子，全局恢复核查仍保留。'})}
async function reviewRecovery(){await task(async()=>{await api('/api/storage/recovery-review','POST',{reason:recoveryReason.value,confirmed:recoveryConfirmed.value});recoveryReason.value='';recoveryConfirmed.value=false;await refreshPresentation();message.value='恢复核查已保存；没有发送动作或自动续跑任务。'})}
async function createBackup(){await task(async()=>{const job=await api<{id:string}>('/api/storage/backup','POST',{});view.value='jobs';message.value='业务备份已受理，可在后台数据任务查看进度和下载。'})}
async function stopAcquisition(){await task(async()=>{acquisition.value=await api('/api/acquisition/stop','POST',{});lastPoll=performance.now();message.value='采集已停止。'})}
const channelDraft=ref<Channel|null>(null),tankDraft=ref<Tank|null>(null);
const serialPorts=ref<string[]>([]),serialPortError=ref(''),serialPortBusy=ref(false);
const serialPortChoices=computed(()=>[...new Set([...serialPorts.value,...(channelDraft.value?.portName?[channelDraft.value.portName]:[])])]);
async function loadSerialPorts(){if(serialPortBusy.value)return;serialPortBusy.value=true;serialPortError.value='';try{serialPorts.value=await api<string[]>('/api/system/serial-ports')}catch(e){serialPortError.value=String(e)}finally{serialPortBusy.value=false}}
watch(()=>channelDraft.value?.id,id=>{if(id)void loadSerialPorts()});
const tankGroupIds=ref<string[]>([]),tankProtocol=ref('DirectRtu'),tankDraftRevision=ref(0);
const groupKindNames:Record<string,string>={Zone:'罐区',TankGroup:'罐组',Medium:'介质',Batch:'设备批次'};
const tankChannels=computed(()=>config.value?.channels.filter(c=>c.protocol===tankProtocol.value)||[]);
const draftChannel=computed(()=>config.value?.channels.find(c=>c.id===tankDraft.value?.channelId));
const draftAddressLabel=computed(()=>tankProtocol.value==='IfxL25'?'表地址':tankProtocol.value.startsWith('Gateway')?'网关槽位号':'仪表站号');
const draftTableAddress=computed({get:()=>tankDraft.value&&draftChannel.value?.protocol==='IfxL25'?ifxTableAddress(tankDraft.value.address,draftChannel.value.unitId):tankDraft.value?.address||0,set:(v:number)=>{if(tankDraft.value)tankDraft.value.address=draftChannel.value?.protocol==='IfxL25'?ifxInternalSlot(v,draftChannel.value.unitId):v}});
function changeTankProtocol(){
 if(!tankDraft.value)return;
 if(draftChannel.value?.protocol!==tankProtocol.value)tankDraft.value.channelId='';
 if(tankProtocol.value==='IfxL25')applyIfxCapabilities(tankDraft.value);
}
function archiveNumber(key:'diameterMm'|'nominalCapacityM3',event:Event){if(!tankDraft.value)return;const value=(event.target as HTMLInputElement).value;tankDraft.value[key]=value===''?null:Number(value)}
watch(()=>tankDraft.value?.id,()=>{tankTab.value='archive';tankDraftRevision.value=config.value?.revision||0;tankGroupIds.value=config.value?.groups.filter(g=>g.tankIds.includes(copyGroupSource.value||tankDraft.value?.id||'')).map(g=>g.id)||[];copyGroupSource.value=null;
 tankEditorError.value='';
 tankProtocol.value=draftChannel.value?.protocol||'DirectRtu';
 if(tankDraft.value && tankProtocol.value==='IfxL25')applyIfxCapabilities(tankDraft.value);
});
const admin=computed(()=>identity.value?.user?.role==='Administrator');
const categories=['all','报警事件','操作日志','系统事件','通讯异常','仪表诊断','任务错误'];
const protocolNames:Record<string,string>={DirectRtu:'直连RS-485 Modbus RTU',IfxL25:'IFX30000',GatewayTcp:'GT6757X Modbus TCP',GatewayRtu:'GT6757X Modbus RTU'};
const shapeNames:Record<string,string>={Vertical:'立式罐',Sphere:'球罐',FloatingRoof:'浮顶罐'};
const tempNames:Record<string,string>={None:'不带温度计',Ats:'多点温度计',Wireless:'无线浮子'};
const titles:Record<string,string>={overview:'罐区总览',list:'罐清单列表',detail:'单罐详情',tanks:'储罐配置',channels:'通讯通道',events:'事件记录',system:'系统管理',history:'历史数据',tables:'罐容表管理',groups:'罐组管理',media:'介质资料',units:'显示单位',jobs:'后台数据任务',snapshots:'数据快照',schedules:'定时任务',alarms:'报警中心',trends:'趋势曲线',wireless:'平均温度测量'};
const enabledCount=computed(()=>config.value?.tanks.filter(t=>t.enabled).length||0);
function quantity(r:LiveReading|undefined,m:Metric|undefined,q:Quantity){return config.value&&liveValid(r)?displayMetric(m,q,config.value.display):'—'}
function unitName(q:Quantity){return config.value?unit(q,config.value.display):''}
function groupMembers(id:string){const selected=new Set([id]),members=new Set<string>();let changed=true;while(changed){changed=false;for(const g of config.value?.groups||[])if(g.parentId&&selected.has(g.parentId)&&!selected.has(g.id)){selected.add(g.id);changed=true}}for(const g of config.value?.groups||[])if(selected.has(g.id))for(const tid of g.tankIds)members.add(tid);return members}
const rangeTanks=computed(()=>{const members=groupFilter.value==='all'?null:groupMembers(groupFilter.value);return (config.value?.tanks||[]).filter(t=>(!members||members.has(t.id))&&(mediumFilter.value==='all'||t.mediumId===mediumFilter.value))});
const summaryTanks=computed(()=>rangeTanks.value.filter(t=>t.enabled&&!t.hidden));
const onlineCount=computed(()=>summaryTanks.value.filter(t=>overviewOnline(t)).length);
const rangeHiddenCount=computed(()=>rangeTanks.value.filter(t=>t.hidden).length);
const rangeAlarmCount=computed(()=>{if(!alarmSummary.value||alarmError.value)return null;const ids=new Set(rangeTanks.value.filter(t=>t.enabled).map(t=>t.id));return alarmSummary.value.tanks.filter(a=>ids.has(a.tankId)).reduce((n,a)=>n+a.active,0)});
const searchableTanks=computed(()=>{const query=overviewSearch.value.trim().toLocaleLowerCase('zh-CN');return rangeTanks.value.filter(t=>!t.hidden&&(!query||[t.code,t.name,t.instrumentTag,t.medium].some(v=>(v||'').toLocaleLowerCase('zh-CN').includes(query)))).sort((a,b)=>a.pinnedAtUtc&&b.pinnedAtUtc?Date.parse(a.pinnedAtUtc)-Date.parse(b.pinnedAtUtc):a.pinnedAtUtc?-1:b.pinnedAtUtc?1:a.code.localeCompare(b.code,'zh-CN',{numeric:true}))});
function overviewInvalid(t:Tank){return t.enabled&&!overviewOnline(t)}
function overviewAttention(t:Tank){if(!t.enabled)return false;const r=reading(t.id);return overviewHasAlarm(t)||overviewInvalid(t)||!!r?.instrumentFault||!!r?.instrumentFaults.length||t.temperatureMode!=='None'&&r?.instantTemperatureC.quality!=='Good'||t.temperatureMode==='Ats'&&(r?.averageTemperatureC.quality!=='Good'||!!r?.atsPoints.some(p=>p.temperatureC.quality!=='Good'))||t.metering.enabled&&(r?.netVolumeM3.quality!=='Good'||r?.massT.quality!=='Good')}
function overviewWorkName(t:Tank){const r=reading(t.id);if(!t.enabled||!liveValid(r)||r?.instrumentStatus===null||r?.instrumentStatus===undefined)return '';const protocol=config.value?.channels.find(c=>c.id===t.channelId)?.protocol;const modes:Record<number,string>=protocol==='IfxL25'?{2:'上升',3:'下降',4:'测界位',6:'测罐底',7:'远程测密'}:{2:'上升',8:'重复性检查',16:'测界位',32:'测罐底',64:'远程测密',128:'震荡回避',256:'下降'};return modes[r.instrumentStatus&(protocol==='IfxL25'?7:0x01ff)]||''}
function overviewWorking(t:Tank){return !!overviewWorkName(t)}
function matchesOverviewStatus(t:Tank,status:string){return status==='all'||status==='attention'&&overviewAttention(t)||status==='working'&&overviewWorking(t)||status==='invalid'&&overviewInvalid(t)}
function overviewStatusCount(status:string){return searchableTanks.value.filter(t=>matchesOverviewStatus(t,status)).length}
const visibleTanks=computed(()=>searchableTanks.value.filter(t=>matchesOverviewStatus(t,overviewStatus.value)));
function total(field:'netVolumeM3'|'massT',q:Quantity){let sum=0,count=0;for(const t of summaryTanks.value){const r=reading(t.id),m=r?.[field];if(liveValid(r)&&m?.quality==='Good'&&m.value!==null){sum+=m.value;count++}}return {value:count&&config.value?displayMetric({value:sum,quality:'Good',isValid:true},q,config.value.display):'—',count}}

const listColumns=computed(()=>{const d=config.value?.display;return [{key:'code',label:'罐号'},{key:'medium',label:'介质'},{key:'level',label:'液位 '+unitName('level'),digits:1},{key:'levelState',label:'液位状态 / 依据'},{key:'instant',label:'温度 ℃',digits:2},{key:'average',label:'平均温度 ℃',digits:2},{key:'averageTime',label:'均温时间 / 来源'},{key:'density',label:'仪表实测密度 '+unitName('density'),digits:1},{key:'manualDensity',label:'人工工况密度 '+unitName('density'),digits:1},{key:'volume',label:'当前净体积 '+unitName('volume'),digits:d?.volumeDecimals??3},{key:'mass',label:'产品质量 '+unitName('mass'),digits:d?.massDecimals??3},{key:'pressure1',label:'压力1 kPa',digits:3},{key:'pressure2',label:'压力2 kPa',digits:3},{key:'state',label:'采集状态'},{key:'alarm',label:'报警状态'},{key:'received',label:'接收时间'}].filter(c=>averageDelivered.value||config.value?.tanks.some(t=>t.temperatureMode==='Ats')||!['average','averageTime'].includes(c.key))});
const listRows=computed(()=>visibleTanks.value.map(t=>{const r=reading(t.id),valid=liveValid(r);function value(m:Metric|undefined,q:Quantity){return valid&&m?.isValid&&m.value!==null&&config.value?converted(m.value,q,config.value.display):null}const old=t.temperatureMode==='Wireless'&&averageDelivered.value&&r?.averageTaskId;const average=old&&r?.averageTemperatureC.isValid&&r.averageTemperatureC.value!==null&&config.value?converted(r.averageTemperatureC.value,'temperature',config.value.display):value(r?.averageTemperatureC,'temperature');return {tankId:t.id,pinned:!!t.pinnedAtUtc,cells:{code:t.code,medium:t.medium,level:value(r?.levelMm,'level'),levelState:valid?(r?.surfaceBasis||r?.levelMm.reason||qualityNames[r?.levelMm.quality||'Missing']):'离线、等待或过期',instant:value(r?.instantTemperatureC,'temperature'),average,averageTime:old?'上次完成 '+new Date(r!.averageCompletedAtUtc!).toLocaleString('zh-CN',{hour12:false}):t.temperatureMode==='Ats'?'温度计实时平均':'未配置',density:t.metering.showInstrumentDensity===false?null:value(r?.instrumentDensityKgM3,'density'),manualDensity:t.metering.manualOperatingDensityKgM3&&config.value?converted(t.metering.manualOperatingDensityKgM3,'density',config.value.display):null,volume:value(r?.netVolumeM3,'volume'),mass:value(r?.massT,'mass'),pressure1:valid&&r?.pressure1KPa.isValid?r.pressure1KPa.value:null,pressure2:valid&&r?.pressure2KPa.isValid?r.pressure2KPa.value:null,state:valid?(r?.diagnostic||'在线'):t.enabled?'离线、等待或过期':'已停用',alarm:alarmText(t),received:r?.receivedAtUtc&&Date.parse(r.receivedAtUtc)>0?new Date(r.receivedAtUtc).toLocaleString('zh-CN',{hour12:false}):'—'}}}));

function mediumStyle(t:Tank){const color=config.value?.media.find(m=>m.id===t.mediumId)?.color;return color?{color,borderColor:color}:{}}
async function displayAction(t:Tank,action:string){if(unsaved.value){error.value='请先保存或重新载入待保存配置';return}await task(async()=>{config.value=await api('/api/tanks/'+t.id+'/display','POST',{configurationRevision:config.value?.revision,action});await refreshAcquisition();message.value='显示设置已保存，所有用户共用。'})}
async function task(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function reload(){identity.value=await getSession();await refreshPresentation();if(identity.value.user){config.value=await api<Configuration>('/api/config');persistedRetention.value=config.value.retentionMonths;unsaved.value=false;if(admin.value)storage.value=await api('/api/storage/health');capacitySummaries.value=await api('/api/capacity-tables');await refreshAcquisition()}}
async function authenticate(){await task(async()=>{if(identity.value?.needsSetup){await api('/api/auth/setup','POST',{login:login.value,displayName:displayName.value,password:password.value});identity.value=await getSession();message.value='管理员已建立，请登录';password.value=''}else{await api('/api/auth/login','POST',{login:login.value,password:password.value});password.value='';await reload()}})}
async function logout(){closePrintPreview();await task(async()=>{await api('/api/auth/logout','POST',{});config.value=null;events.value=[];storage.value=null;identity.value=await getSession()})}
async function save(){await task(async()=>{if(!config.value)return;const payload=clone(config.value);payload.channels=payload.channels.map(({isGateway,physicalKey,...c})=>c);if(payload.retentionMonths<persistedRetention.value){if(!retentionBackup.value||!retentionConfirmed.value)throw Error('请在系统管理的数据库维护中选择当前配置版本的有效备份，并确认缩短期限');config.value=await api<Configuration>('/api/storage/retention-change','POST',{configuration:payload,backupId:retentionBackup.value,confirmed:retentionConfirmed.value})}else config.value=await api<Configuration>('/api/config','PUT',payload);persistedRetention.value=config.value.retentionMonths;retentionBackup.value='';retentionConfirmed.value=false;unsaved.value=false;await refreshAcquisition();message.value='配置已保存。采集服务已应用新配置，未向仪表发送控制。'})}
async function tablesUpdated(c:Configuration){config.value=c;persistedRetention.value=c.retentionMonths;unsaved.value=false;capacitySummaries.value=await api('/api/capacity-tables');await refreshAcquisition()}
async function choose(v:string){if(v==='detail'&&!config.value?.tanks.some(t=>t.id===detailTank.value&&!t.hidden))detailTank.value=config.value?.tanks.find(t=>!t.hidden)?.id||'';view.value=v;error.value='';message.value='';await nextTick();window.scrollTo(0,0);if(v==='events'&&licensed.value&&can('HistoryRead'))await task(loadEvents);if(v==='system')await task(loadBackups);if(v==='tanks')capacitySummaries.value=await api('/api/capacity-tables')}
async function loadEvents(){if(!licensed.value)return;const q=new URLSearchParams({category:category.value,tank:filterTank.value,keyword:keyword.value,actor:actor.value,limit:'1000'});if(start.value)q.set('start',new Date(start.value).toISOString());if(end.value)q.set('end',new Date(end.value).toISOString());const result=await api<EventRow[]>('/api/events?'+q);if(licensed.value)events.value=result}
function resetFilter(){category.value='all';filterTank.value='all';keyword.value='';actor.value='';start.value='';end.value='';void task(loadEvents)}
function addChannel(){channelDraft.value={id:crypto.randomUUID(),name:'',protocol:'DirectRtu',portName:'',baudRate:4800,dataBits:8,parity:'Even',stopBits:1,host:'',tcpPort:502,unitId:1,pollIntervalMs:3000,readTimeoutMs:1000,readRetries:1,enabled:true}}
function channelProtocol(){const d=channelDraft.value;if(!d)return;if(d.protocol==='IfxL25'){d.baudRate=38400;d.parity='Even';d.stopBits=1;d.unitId=1}else if(d.protocol==='DirectRtu')d.baudRate=4800;else if(d.protocol==='GatewayRtu')d.baudRate=38400}
function acceptChannel(){if(!config.value||!channelDraft.value)return;const d=clone(channelDraft.value);d.name=d.name.trim();if(!d.name){error.value='请填写通道名称';return}const i=config.value.channels.findIndex(x=>x.id===d.id);if(i<0)config.value.channels.push(d);else config.value.channels[i]=d;channelDraft.value=null;unsaved.value=true}
function emptyAlarms():AlarmSettings{const limits=()=>({lowLow:null,low:null,high:null,highHigh:null,hysteresis:0,delaySeconds:0});return {level:limits(),temperature:limits(),density:limits(),pressure1:limits(),pressure2:limits(),communicationEnabled:true,instrumentEnabled:true}}
function alarmColor(t:Tank){const a=alarmSummary.value?.tanks.find(a=>a.tankId===t.id);return a?.active?'#d96c62':a?.recoveredUnacknowledged?'#d7ae53':'#73afa1'}
function alarmText(t:Tank){const a=alarmSummary.value?.tanks.find(a=>a.tankId===t.id);return a?.active?'活动报警 '+a.active+(a.unacknowledged?' · 待确认':' · 已确认'):a?.recoveredUnacknowledged?'已恢复 · 待确认':'无活动报警'}
function overviewOnline(t:Tank){const r=reading(t.id);return t.enabled&&liveValid(r)&&r?.levelMm.quality==='Good'}
function overviewFrozen(t:Tank){const r=reading(t.id);return t.enabled&&hasFrozenSurface(r,liveValid(r),config.value?.channels.find(c=>c.id===t.channelId)?.protocol)}
function overviewLevel(t:Tank){const r=reading(t.id);return overviewFrozen(t)?r!.lastMeasuredLevelMm!:r?.levelMm.value??null}
function overviewLevelText(t:Tank){const r=reading(t.id);return quantity(r,overviewFrozen(t)?{value:r!.lastMeasuredLevelMm!,quality:'Good',isValid:true}:r?.levelMm,'level')}
function overviewFrozenNote(t:Tank){return overviewFrozen(t)?'液位冻结于 '+new Date(reading(t.id)!.lastMeasuredLevelAtUtc!).toLocaleString('zh-CN',{hour12:false}):''}
function overviewState(t:Tank){if(!t.enabled)return '已停用';if(!acquisition.value?.running)return '采集已停止';const r=reading(t.id);if(!liveValid(r))return '离线 / 过期';if(overviewFrozen(t))return '液位冻结';return r?.levelMm.quality==='Good'?'在线':qualityNames[r?.levelMm.quality||'Missing']}
function overviewHasAlarm(t:Tank){const a=alarmSummary.value?.tanks.find(a=>a.tankId===t.id);return !!(a?.active||a?.recoveredUnacknowledged)}
function overviewFootnote(t:Tank){if(overviewHasAlarm(t))return alarmText(t);if(!overviewOnline(t))return reading(t.id)?.diagnostic||overviewState(t);if(overviewWorking(t))return overviewWorkName(t)+' · 作业中';if(alarmError.value)return '报警状态读取失败';if(!alarmSummary.value)return '正在读取报警状态';const r=reading(t.id);return r?.diagnostic||new Date(r!.receivedAtUtc).toLocaleTimeString('zh-CN',{hour12:false})+' 更新'}
function overviewAverage(t:Tank){const r=reading(t.id);if(t.temperatureMode==='Ats')return quantity(r,r?.averageTemperatureC,'temperature');return r?.averageTaskId&&config.value?displayMetric(r.averageTemperatureC,'temperature',config.value.display):'—'}
function overviewAverageTime(t:Tank){const time=reading(t.id)?.averageCompletedAtUtc;return time?new Date(time).toLocaleString('zh-CN',{hour12:false}):'尚无成功记录'}

function addTank(){if(!config.value?.channels.length){error.value='请先配置采集通道';return}if(config.value.tanks.length>=128){error.value='最多配置128个罐';return}newIdentity.value={tag:'',code:''};identityError.value=''}
function createTankDraft(){if(!config.value?.channels.length){error.value='请先配置采集通道';return}if(config.value.tanks.length>=128){error.value='最多配置128个罐';return}tankDraft.value={id:crypto.randomUUID(),code:'',name:'',productNumber:'',batch:'',diameterMm:null,nominalCapacityM3:null,notes:'',instrumentTag:'',medium:'',mediumId:null,pinnedAtUtc:null,atsHeightsMm:[],pressure1:{enabled:false,at4Ma:0,at20Ma:100,unit:'KPa'},pressure2:{enabled:false,at4Ma:0,at20Ma:100,unit:'KPa'},zone:'',channelId:config.value.channels[0].id,address:1,shape:'Vertical',heightMm:12000,temperatureMode:'None',atsPointCount:1,enabled:true,hidden:false,controls:{allowedCommands:[...basicOperations],wirelessMeasurementEnabled:false,confirmationTimeoutSeconds:30,movementTimeoutSeconds:600},trends:{quantities:['Level','NetVolume','Mass'],colors:['#318c9b','#b27852','#75934b']},alarms:emptyAlarms(),metering:{enabled:false,mainTableId:null,staticPressureTableId:null,decimalTableId:null,waterHeightMm:0,waterVolumeM3:0,standardDensity20KgM3:null,manualOperatingDensityKgM3:null,densitySource:"Instrument",showInstrumentDensity:true,baseVolumeMethod:"Interpolate",fractionalMillimetreRule:"Linear"}}}
function copyTank(t:Tank){if((config.value?.tanks.length||0)>=128){error.value="最多配置128个罐";return}copyGroupSource.value=t.id;tankDraft.value=clone(t);Object.assign(tankDraft.value,{id:crypto.randomUUID(),code:"",instrumentTag:"",name:(t.name||t.code)+"（副本）",address:0});tankDraft.value.controls.allowedCommands=tankDraft.value.controls.allowedCommands.filter(operationAvailable);message.value="已复制已开放参数、分组、启用状态及罐容表；请填写新罐号和通讯地址，核对后保存。"}
function acceptTank(){if(!config.value||!tankDraft.value)return;if(config.value.revision!==tankDraftRevision.value){tankEditorError.value='配置已被其他用户更新，请关闭并重新打开储罐配置后再修改';return}const t=clone(tankDraft.value);for(const key of ['name','productNumber','batch','notes'] as const)t[key]=(t[key]||'').trim();t.atsHeightsMm=t.atsHeightsMm.map(v=>typeof v==='number'&&Number.isFinite(v)?v:null);t.code=t.code.trim();if(!t.code){tankTab.value='archive';tankEditorError.value='请填写罐号';return}
 t.instrumentTag=t.instrumentTag.trim();if(!t.instrumentTag){tankTab.value='archive';tankEditorError.value='请填写唯一仪表位号';return}
 const others=config.value.tanks.filter(x=>x.id!==t.id);if(others.some(x=>x.instrumentTag.trim().toLowerCase()===t.instrumentTag.toLowerCase())){tankTab.value='archive';tankEditorError.value='仪表位号已被使用';return}
 if(others.some(x=>x.code.trim().toLowerCase()===t.code.toLowerCase())){
  tankTab.value='archive';tankEditorError.value='罐号 '+t.code+' 已被使用，请填写其他罐号';return;
 }
 const conflict=others.find(x=>x.channelId===t.channelId && x.address===t.address);
 if(conflict){
  tankTab.value='binding';tankEditorError.value=t.code+' 的'+draftAddressLabel.value+'与 '+conflict.code+' 重复，请修改';return;
 }
 const i=config.value.tanks.findIndex(x=>x.id===t.id);if(i<0)config.value.tanks.push(t);else config.value.tanks[i]=t;for(const g of config.value.groups){g.tankIds=g.tankIds.filter(id=>id!==t.id);if(tankGroupIds.value.includes(g.id))g.tankIds.push(t.id)}tankDraft.value=null;unsaved.value=true}
function removeChannel(c:Channel){if(config.value?.tanks.some(t=>t.channelId===c.id)){error.value='此通道仍有储罐绑定，请先修改罐的绑定';return}if(confirm('删除通道 '+c.name+'？保存配置后生效。')&&config.value){config.value.channels=config.value.channels.filter(x=>x.id!==c.id);unsaved.value=true}}
function removeTank(t:Tank){if(config.value?.schedules.some(s=>s.tankIds?.includes(t.id))){error.value='该罐仍在定时任务中，请先修改任务的储罐选择';return}if(confirm('删除储罐 '+t.code+'？历史及事件保留，保存配置后生效。')&&config.value){config.value.tanks=config.value.tanks.filter(x=>x.id!==t.id);for(const g of config.value.groups)g.tankIds=g.tankIds.filter(id=>id!==t.id);unsaved.value=true}}
function exportEvents(){if(!licensed.value||!can('DataExport'))return;window.LocalWorkbook.download('事件查询结果',[{name:'事件记录',rows:[['时间','类型','储罐','内容','结果','操作或记录人员'],...events.value.map(e=>[new Date(e.atUtcMs).toLocaleString('zh-CN',{hour12:false}),e.category,e.tankCode,e.content,e.result,e.actorName])]}])}
async function expiredSession(){config.value=null;events.value=[];storage.value=null;acquisition.value=null;identity.value=await getSession();error.value='登录已失效，请重新登录'}
onMounted(async()=>{window.addEventListener('level-session-expired',expiredSession);await task(reload);pollTimer=setInterval(()=>{tick.value=performance.now();if(identity.value?.user&&!busy.value&&performance.now()-lastPoll>=(config.value?.display.refreshIntervalSeconds||1)*1000)void refreshAcquisition().catch(()=>{connectionIssue.value=true})},1000)});onUnmounted(()=>{window.removeEventListener('level-session-expired',expiredSession);if(pollTimer)clearInterval(pollTimer)});
</script>
<template>
 <div v-if="!identity?.user" class="login-shell"><section class="panel login-card"><span class="eyebrow">LEVEL MANAGEMENT</span><h1>{{presentation.branding.softwareName}}</h1><p>{{identity?.needsSetup?'首次使用，请在本机建立管理员':'登录系统'}}</p><form @submit.prevent="authenticate"><label class="config-field">账号<input v-model="login" name="login" required autocomplete="username" maxlength="60"></label><label v-if="identity?.needsSetup" class="config-field">姓名<input v-model="displayName" name="displayName" required maxlength="80"></label><label class="config-field">密码<input v-model="password" name="password" type="password" required minlength="8" maxlength="128" :autocomplete="identity?.needsSetup?'new-password':'current-password'"></label><button class="button primary" :disabled="busy||!identity">{{identity?.needsSetup?'建立管理员':'登录'}}</button></form><p v-if="error" class="error-message">{{error}}</p><p v-if="message" class="success-message">{{message}}</p><small>V0.3.0 · r24 · 仪表操作按逐罐配置和账号权限开放</small></section></div>
 <template v-else>
 <aside class="sidebar" :class="{collapsed:sidebarCollapsed}"><button class="sidebar-toggle" :title="sidebarCollapsed?'展开菜单':'收起菜单'" aria-label="切换侧栏" :aria-expanded="!sidebarCollapsed" @click="sidebarCollapsed=!sidebarCollapsed"><UiIcon name="menu"/></button><BrandHeader :branding="presentation.branding"/><div class="workspace-name">V0.3.0 · r24</div><div class="nav-label">监控工作空间</div><nav><button v-for="item in [['overview','罐区总览'],['list','罐清单列表'],['detail','单罐详情'],['history','历史数据'],['trends','趋势曲线'],['wireless','平均温度测量'],['snapshots','数据快照'],['alarms','报警中心'],['events','事件记录']].filter(item=>(item[0]!=='wireless'||averageDelivered)&&(!['history','snapshots','events'].includes(item[0])||can('HistoryRead')))" :key="item[0]" :title="item[1]" :aria-label="item[1]" :class="{active:view===item[0],'alarm-attention':item[0]==='alarms'&&(alarmSummary?.unacknowledged||0)>(alarmSummary?.recoveredUnacknowledged||0),'alarm-present':item[0]==='alarms'&&(alarmSummary?.active||0)>0}" @click="choose(item[0])"><UiIcon :name="item[0]"/><span>{{item[1]}}</span></button><button :aria-expanded="reportsOpen" @click="reportsOpen=!reportsOpen"><UiIcon name="reports"/><span>报表中心</span><small class="nav-disclosure">{{reportsOpen?'−':'+'}}</small></button><template v-if="reportsOpen"><button v-for="name in ['单罐作业报表','罐区产品汇总报表','动态即时报表']" :key="name" class="nested-nav" disabled>{{name}} · 暂未启用</button></template></nav><div class="nav-label secondary-label">配置与管理</div><nav><button v-for="item in [['tanks','储罐配置'],['channels','通讯通道'],['basics','基础数据'],['groups','罐组管理'],['jobs','后台数据任务'],['system','系统管理']]" :key="item[0]" :title="item[1]" :aria-label="item[1]" :class="{active:view===item[0]||item[0]==='basics'&&basicViews.includes(view)}" @click="choose(item[0]==='basics'?'tables':item[0])"><UiIcon :name="item[0]"/><span>{{item[1]}}</span></button></nav><div class="sidebar-bottom">液位管理系统 · r24</div></aside>
 <div class="app-shell" :class="{'sidebar-is-collapsed':sidebarCollapsed,'records-shell':['history','events'].includes(view)}"><header class="topbar"><span>监控中心 / {{titles[view]}}</span><div><button v-if="desktopBridge" class="text-button desktop-downloads" @click="showDownloads"><UiIcon name="download"/>下载文件</button><button class="text-button" @click="choose('alarms')">待确认报警 {{alarmSummary?.unacknowledged||0}}</button><span class="stage-badge" :class="{'acquisition-running':acquisition?.running}">{{acquisition?.running?'采集运行中':'采集已停止'}}</span><button v-if="can('AcquisitionManage')&&!acquisition?.running" class="text-button" :disabled="busy" @click="startAcquisition">启动采集</button><button v-if="can('AcquisitionManage')&&acquisition?.running" class="text-button acquisition-management" @click="choose('system');systemTab='parameters'">采集管理</button><span>{{identity.user.displayName}}</span><button class="text-button" @click="logout">退出</button></div></header><main :class="{'single-detail-main':view==='detail','overview-main':['overview','list'].includes(view),'events-main':view==='events','records-main':['history','events'].includes(view)}">
 <p v-if="authorization&&(authorization.state!=='Active'||authorization.reminderDays)" class="notice authorization-notice">{{authorization.message}}<span v-if="authorization.expiresAtUtc"> · 截止 {{new Date(authorization.expiresAtUtc).toLocaleString('zh-CN',{hour12:false})}}</span></p><div v-if="view!=='detail'" class="page-heading"><div><div class="eyebrow">LEVEL MANAGEMENT</div><h1>{{titles[view]}}</h1><p class="subtitle">{{view==='overview'?'实时液位、温度与库存，一屏掌握罐区状态':'监控储罐状态，查询测量数据与事件记录'}}</p></div><div class="heading-actions"><button v-if="(['tanks','channels','groups','media','units','schedules'].includes(view)||view==='system'&&['parameters','database'].includes(systemTab))&&canConfigure" class="button" @click="task(reload)">重新载入</button><button v-if="(['tanks','channels','groups','media','units','schedules'].includes(view)||view==='system'&&['parameters','database'].includes(systemTab))&&canConfigure" class="button primary" :disabled="busy" @click="save">保存配置{{unsaved?' *':''}}</button></div></div>
 <div v-if="alarmError" class="notice error-message">{{alarmError}}</div><div v-if="connectionIssue" class="notice error-message">后台通讯异常，过期读数自动显示为“—”。</div><div v-if="acquisition?.historyError" class="notice error-message">{{acquisition.historyError}}</div><div v-if="error" role="alert" class="notice error-message">{{error}}</div><div v-if="message" role="status" class="notice success-message">{{message}}</div><div v-if="unsaved" class="notice">有未保存的修改，点击“保存配置”后统一校验并入库。</div>
<div v-if="basicViews.includes(view)" class="tabs basic-data-tabs" role="tablist" aria-label="基础数据"><button v-for="[key,label] in basicTabs" :key="key" role="tab" :aria-selected="view===key" :class="{active:view===key}" @click="choose(key)">{{label}}</button></div>
 <template v-if="['overview','list'].includes(view)"><div class="overview-heading-actions"><button v-if="canConfigure" class="button primary" :disabled="busy||unsaved||!licensed" @click="choose('tanks').then(addTank)">＋ 新增储罐</button></div><div class="overview-sticky"><div class="overview-range-controls"><div class="overview-scope-fields"><label>分组<select v-model="overviewGroupKind" aria-label="总览分组类型"><option value="all">全部分组类型</option><option v-for="(name,key) in groupKindNames" :key="key" :value="key">{{name}}</option></select></label><label><span class="sr-only">具体分组</span><select v-model="groupFilter" aria-label="总览分组"><option value="all">全部范围</option><option v-for="g in overviewGroupOptions" :key="g.id" :value="g.id">{{g.name}}</option></select></label><label>介质<select v-model="mediumFilter" aria-label="总览介质"><option value="all">全部介质</option><option v-for="m in config?.media" :key="m.id" :value="m.id">{{m.name}}</option></select></label></div><div class="overview-search-view"><label v-if="view==='overview'&&overviewView==='cards'" class="overview-card-size">卡片大小<select v-model="overviewCardSize" aria-label="卡片大小" title="仅保存到本机浏览器，不改变置顶与库存统计"><option value="compact">紧凑</option><option value="standard">标准</option><option value="large">大号</option></select></label><input v-model="overviewSearch" type="search" aria-label="总览搜索" placeholder="搜索罐号 / 名称 / 介质"><div class="overview-view-switch" role="group" aria-label="总览显示方式"><button :class="{active:view==='overview'&&overviewView==='cards'}" :aria-pressed="view==='overview'&&overviewView==='cards'" aria-label="图形显示" title="图形显示" @click="setOverviewView('cards')"><UiIcon name="overview"/></button><button :class="{active:view==='list'||overviewView==='list'}" :aria-pressed="view==='list'||overviewView==='list'" aria-label="列表显示" title="列表显示" @click="setOverviewView('list')"><UiIcon name="list"/></button></div></div></div><div class="summary-grid overview-summary overview-range-summary" aria-label="总览范围汇总">
<div class="summary-card" data-summary="tanks"><div class="summary-label">所选范围储罐</div><div class="summary-value"><span class="summary-number">{{rangeTanks.length}}</span><small>个</small></div><small class="summary-description">参与合计 {{summaryTanks.length}} 罐 · 在线 {{onlineCount}} 罐</small></div>
<div class="summary-card" data-summary="volume"><div class="summary-label">当前净体积合计</div><div class="summary-value"><span class="summary-number">{{total('netVolumeM3','volume').value}}</span><small>{{unitName('volume')}}</small></div><small class="summary-description">计入 {{total('netVolumeM3','volume').count}} 罐 · 数据不足 {{summaryTanks.length-total('netVolumeM3','volume').count}} 罐</small></div>
<div class="summary-card" data-summary="mass"><div class="summary-label">产品质量合计</div><div class="summary-value"><span class="summary-number">{{total('massT','mass').value}}</span><small>{{unitName('mass')}}</small></div><small class="summary-description">计入 {{total('massT','mass').count}} 罐 · 数据不足 {{summaryTanks.length-total('massT','mass').count}} 罐</small></div>
<div class="summary-card" data-summary="alarms"><div class="summary-label">活动报警</div><button class="summary-value summary-alarm" aria-label="打开报警中心（全系统）" title="此处统计所选范围；点击进入全系统报警中心，可再按储罐筛选" @click="choose('alarms')"><span class="summary-number">{{rangeAlarmCount??'—'}}</span><small>项</small></button><small class="summary-description">所选范围 · 包含隐藏罐报警</small></div>
</div><div v-if="!config?.tanks.length" class="panel empty">尚未配置储罐。请先在“通讯通道”新增通道，再增加储罐。</div><div class="overview-status-row"><div class="tabs overview-status-tabs" role="group" aria-label="总览状态筛选"><button v-for="[key,label] in overviewStatusOptions" :key="key" :class="{active:overviewStatus===key}" :aria-pressed="overviewStatus===key" :aria-label="'总览状态 '+label" :title="key==='working'?'按有效仪表模式统计升降、测界位、测罐底、密度等作业；普通轮询不算作业':key==='invalid'?'液位无效、通讯中断、过期或等待；其他数据项异常可在需关注查看':label" @click="overviewStatus=key">{{label}}<span>{{overviewStatusCount(key)}}</span></button></div><button class="text-button" @click="choose('groups')">{{canConfigure?'管理罐组':'查看罐组'}} →</button></div><div class="overview-scope-note"><span>显示 {{visibleTanks.length}} / {{rangeTanks.filter(t=>!t.hidden).length}} 罐 · 合计按所选分组和介质统计，不受搜索和状态页签影响；隐藏、停用不计库存。</span><button v-if="canConfigure&&rangeHiddenCount" class="text-button" @click="choose('tanks')">管理隐藏罐（{{rangeHiddenCount}}）</button></div></div><div v-if="view==='overview'&&overviewView==='cards'" class="tank-grid" :class="'card-size-'+overviewCardSize" :data-card-size="overviewCardSize"><article v-for="t in visibleTanks" :key="t.id" class="panel engineering-tank overview-card"><div class="tank-card-heading"><h2 :title="t.name||t.code">{{t.instrumentTag||t.code}}</h2><div class="overview-card-actions"><span class="overview-connection" :class="{unavailable:!overviewOnline(t),frozen:overviewFrozen(t)}" :title="overviewFrozenNote(t)||reading(t.id)?.diagnostic||overviewState(t)">{{overviewState(t)}}</span><button v-if="canConfigure" class="pin-button" :class="{pinned:!!t.pinnedAtUtc}" :title="t.pinnedAtUtc?'取消置顶':'置顶'" :aria-label="t.code+(t.pinnedAtUtc?'取消置顶':'置顶')" :disabled="busy||unsaved" @click="displayAction(t,t.pinnedAtUtc?'Unpin':'Pin')"><UiIcon name="pin"/></button></div></div><p class="overview-card-identity" :title="t.name"><span class="overview-tank-code">{{t.code}} · </span><span class="medium-chip" :style="mediumStyle(t)">{{t.medium||'介质未填'}}</span><span class="overview-shape"> · {{shapeNames[t.shape]}}</span></p><div class="engineering-tank-content"><TankGraphic :shape="t.shape" :height="t.heightMm" :color="overviewFrozen(t)?'#bbc7cc':alarmColor(t)" :level="overviewLevel(t)" :good="overviewFrozen(t)||liveValid(reading(t.id))&&reading(t.id)?.levelMm.quality==='Good'" :show-percent="false"/><div class="overview-key-values"><small>液位 {{unitName('level')}}</small><strong class="overview-level" :class="{frozen:overviewFrozen(t)}" :title="overviewFrozenNote(t)">{{overviewLevelText(t)}}</strong><small>温度</small><h2>{{quantity(reading(t.id),reading(t.id)?.instantTemperatureC,'temperature')}} <small>℃</small></h2><template v-if="t.temperatureMode==='Ats'||t.temperatureMode==='Wireless'&&averageDelivered"><small>{{t.temperatureMode==='Ats'?'实时平均温度':'最近平均温度'}}</small><h2 class="overview-average" :title="t.temperatureMode==='Wireless'?'最近一次成功完成：'+overviewAverageTime(t):'正常读取点的实时算术平均'">{{overviewAverage(t)}} <small>℃</small></h2></template></div></div><div class="overview-card-inventory"><div v-if="t.metering.showInstrumentDensity!==false"><small class="inventory-label">仪表密度</small><small class="inventory-unit">{{unitName('density')}}</small><strong>{{quantity(reading(t.id),reading(t.id)?.instrumentDensityKgM3,'density')}}</strong></div><div><small class="inventory-label">人工工况密度</small><small class="inventory-unit">{{unitName('density')}}</small><strong>{{t.metering.manualOperatingDensityKgM3?displayMetric({value:t.metering.manualOperatingDensityKgM3,quality:'Good',isValid:true},'density',config!.display):'—'}}</strong></div><div><small class="inventory-label">净体积</small><small class="inventory-unit">{{unitName('volume')}}</small><strong>{{quantity(reading(t.id),reading(t.id)?.netVolumeM3,'volume')}}</strong></div><div><small class="inventory-label">质量</small><small class="inventory-unit">{{unitName('mass')}}</small><strong>{{quantity(reading(t.id),reading(t.id)?.massT,'mass')}}</strong></div></div><div class="overview-card-footer"><span class="overview-card-status" :style="overviewHasAlarm(t)?{color:alarmColor(t)}:undefined" :class="{alarm:overviewHasAlarm(t),unavailable:!overviewOnline(t)}" :title="overviewFootnote(t)">{{overviewFootnote(t)}}</span><button class="text-button" @click="detailTank=t.id;choose('detail')">详情 →</button></div></article></div><div v-if="view==='overview'&&overviewView==='cards'&&config?.tanks.length&&!visibleTanks.length" class="panel empty">当前筛选没有储罐</div><CurrentReadings v-if="view==='list'||overviewView==='list'" :columns="listColumns" :rows="listRows" :licensed="licensed" :server-at="acquisition?.serverAtUtc||null" :admin="canConfigure" :busy="busy||unsaved" @pin="displayAction(config!.tanks.find(t=>t.id===$event)!,config!.tanks.find(t=>t.id===$event)!.pinnedAtUtc?'Unpin':'Pin')" @detail="detailTank=$event;choose('detail')"/></template>
 <template v-if="view==='channels'"><div class="toolbar"><span>采集串口按本机实际接口配置；网关编号与Unit ID分开。</span><button v-if="canConfigure" class="button primary" @click="addChannel">新增通道</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>通道</th><th>协议</th><th>连接</th><th>站号 / Unit ID</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="c in config?.channels" :key="c.id"><td>{{c.name}}</td><td>{{protocolNames[c.protocol]}}</td><td>{{c.protocol==='GatewayTcp'?c.host+':'+c.tcpPort:c.portName+' / '+c.baudRate}}</td><td>{{c.unitId}}</td><td>{{c.enabled?'启用':'停用'}}</td><td><button v-if="canConfigure" class="text-button" @click="channelDraft=clone(c)">编辑</button><button v-if="canConfigure" class="text-button" @click="removeChannel(c)">删除</button></td></tr><tr v-if="!config?.channels.length"><td colspan="6" class="empty">尚未配置通道</td></tr></tbody></table></div></section></template>
 <template v-if="view==='tanks'"><TankConfigurationTransfer v-if="canConfigure" :licensed="licensed" :dirty="unsaved" @updated="tablesUpdated"/><div class="toolbar"><span>已配置 {{config?.tanks.length||0}} / 128 个罐</span><button v-if="canConfigure" class="button primary" @click="addTank">新增储罐</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>位号</th><th>罐号</th><th>罐区 / 介质</th><th>采集通道</th><th>表地址 / 仪表地址</th><th>温度类型</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="t in config?.tanks" :key="t.id"><td>{{t.instrumentTag||'—'}}</td><td>{{t.code}}</td><td>{{t.zone||'—'}} / {{t.medium||'—'}}</td><td>{{config?.channels.find(c=>c.id===t.channelId)?.name||'未绑定'}}</td><td>{{config?.channels.find(c=>c.id===t.channelId)?.protocol==='IfxL25'?ifxTableAddress(t.address,config!.channels.find(c=>c.id===t.channelId)!.unitId):t.address}}</td><td>{{tempNames[t.temperatureMode]}}</td><td>{{t.enabled?'启用':'停用'}}{{t.hidden?' / 隐藏':''}}</td><td><button v-if="canConfigure" class="text-button" @click="tankDraft=clone(t)">编辑</button><button v-if="canConfigure" class="text-button" @click="copyTank(t)">复制</button><button v-if="canConfigure" class="text-button" :disabled="busy" @click="displayAction(t,t.hidden?'Show':'Hide')">{{t.hidden?'恢复显示':'隐藏'}}</button><button v-if="canConfigure" class="text-button" @click="removeTank(t)">删除</button></td></tr><tr v-if="!config?.tanks.length"><td colspan="8" class="empty">尚未配置储罐</td></tr></tbody></table></div></section></template>
 <WirelessTasks :focus-tank="averageFocusTank" :licensed="licensed" v-if="view==='wireless'&&config&&averageDelivered" :config="config" :can-operate="!!canOperate" :dirty="unsaved"/>
<p v-if="!licensed&&['events','history','snapshots','jobs'].includes(view)" class="notice" role="status">当前授权限制历史查询、快照与文件下载。实时监控、历史归档、报警确认及当前操作回执继续保留；请在系统状态查看软件授权。</p>
 <template v-if="view==='events'&&licensed&&can('HistoryRead')"><div class="toolbar"><div class="tabs"><button v-for="c in categories" :key="c" :class="{active:category===c}" :disabled="busy" @click="category=c;task(loadEvents)">{{c==='all'?'全部':c}}</button></div><button class="button" :disabled="busy||!can('DataExport')" @click="exportEvents">导出当前结果</button></div><form class="panel query-panel" @submit.prevent="task(loadEvents)"><div class="query-fields"><label class="config-field">储罐<select v-model="filterTank"><option value="all">全部储罐</option><option v-for="t in config?.tanks" :key="t.id" :value="t.id">{{t.code}}</option></select></label><label class="config-field">开始时间<input v-model="start" type="datetime-local"></label><label class="config-field">结束时间<input v-model="end" type="datetime-local"></label><label class="config-field">关键词<input v-model="keyword"></label><label class="config-field">操作 / 记录人员<input v-model="actor"></label></div><div class="inline-actions query-actions"><button class="button primary" :disabled="busy">查询</button><button type="button" class="button" :disabled="busy" @click="resetFilter">重置</button></div></form><section class="panel event-results"><div class="table-wrap"><table><thead><tr><th>时间</th><th>类型</th><th>储罐</th><th>内容</th><th>结果</th><th>人员</th><th>详情</th></tr></thead><tbody><tr v-for="e in events" :key="e.id"><td>{{new Date(e.atUtcMs).toLocaleString('zh-CN',{hour12:false})}}</td><td>{{e.category}}</td><td>{{e.tankCode||'—'}}</td><td>{{e.content}}</td><td>{{e.result}}</td><td>{{e.actorName}}</td><td><button v-if="e.details" class="text-button" @click="details=e">查看</button></td></tr><tr v-if="!events.length"><td colspan="7" class="empty">暂无符合条件的记录</td></tr></tbody></table></div><div class="table-foot">当前 {{events.length}} 条，最多1000条 · 导出与查询一致</div></section></template>
 <template v-if="view==='system'"><div class="tabs"><button :class="{active:systemTab==='parameters'}" @click="systemTab='parameters'">基本参数</button><button :class="{active:systemTab==='accounts'}" @click="systemTab='accounts'">账号与权限</button><button :class="{active:systemTab==='database'}" @click="systemTab='database'">数据库维护</button><button :class="{active:systemTab==='integration'}" @click="systemTab='integration'">对外接口</button><button :class="{active:systemTab==='authorization'}" @click="systemTab='authorization'">软件授权</button></div><ReadOnlyIntegration v-if="systemTab==='integration'&&config" :config="config" :admin="can('IntegrationManage')" :dirty="unsaved"/><Authorization v-if="systemTab==='authorization'" :admin="admin" @updated="refreshPresentation"/><Accounts v-if="systemTab==='accounts'" :admin="admin" :current-account-id="identity?.user?.accountId||''" @signed-out="task(reload)"/><section v-if="systemTab==='parameters'" class="panel panel-body"><h2>采集与历史基础参数</h2><label v-if="config" class="checkbox"><input v-model="config.startReadOnlyAcquisitionAtStartup" type="checkbox" :disabled="!canConfigure" @change="unsaved=true">服务启动后自动开始只读采集（不启动测温或其他仪表操作；恢复数据待核查时不自动开启）</label><div v-if="config" class="config-fields"><label class="config-field">历史保存间隔（秒）<input v-model.number="config.historyIntervalSeconds" type="number" min="1" max="86400" :disabled="!canConfigure" @input="unsaved=true"></label><label class="config-field">数据过期时间（秒，默认30）<input v-model.number="config.readingExpirySeconds" type="number" min="3" max="3600" :disabled="!canConfigure" @input="unsaved=true"></label></div><p class="help">容量基线为128罐、60秒间隔、一年；缩短保存间隔会增加磁盘占用，需按目标条件另行验收。</p><div class="acquisition-actions"><button v-if="can('AcquisitionManage')&&!acquisition?.running" class="button primary" :disabled="busy" @click="startAcquisition">启动采集</button><button v-if="can('AcquisitionManage')&&acquisition?.running" class="button" :disabled="busy" @click="stopAcquisition">停止采集</button><span class="help">配置版本 {{config?.revision}} · 最多128罐 · 默认60秒归档</span></div><h2>采集通道状态</h2><div v-for="c in acquisition?.channels" :key="c.channelId" class="notice">{{c.name}} · {{c.connected?'通道已打开':'连接异常'}} · 周期 {{c.lastCycleMs.toFixed(0)}} ms · 已完成 {{c.completedCycles}} 轮 <span v-if="c.error"> · {{c.error}}</span></div></section><section v-if="systemTab==='database'" class="panel panel-body database-maintenance"><h2>历史数据保留</h2><div v-if="config" class="config-fields"><label class="config-field">保留期限（月）<input v-model.number="config.retentionMonths" type="number" min="1" max="12" :disabled="!canConfigure" @input="unsaved=true"></label></div><details v-if="admin&&config&&config.retentionMonths<persistedRetention"><summary>缩短历史保留期限前的确认</summary><p class="notice">保存后将自动清理超出新期限的历史。请先按原配置创建业务备份，再修改期限；备份须在24小时内、与当前配置版本一致，保存时将重新校验文件。</p><button type="button" class="button" :disabled="busy||!licensed" @click="task(loadBackups)">刷新备份列表</button><label class="config-field">有效业务备份<select v-model="retentionBackup"><option value="">请选择</option><option v-for="b in backupChoices.filter(b=>b.kind==='DatabaseBackup'&&b.state==='Completed')" :key="b.id" :value="b.id">{{new Date(b.createdAtUtc).toLocaleString('zh-CN')}} · {{b.id.slice(0,8)}}</option></select></label><label class="checkbox"><input v-model="retentionConfirmed" type="checkbox">我已保存业务备份，确认缩短期限会自动清理超出新期限的历史</label></details><h2>恢复后的现场核查</h2><p class="notice">{{recovery?.message||'正在核对独立写入证据'}}</p><form v-if="recovery?.requiresReview&&admin" @submit.prevent="reviewRecovery"><p class="help">请核对恢复后的罐体清单、接线与地址、实际浮子运动和仪表模式。先逐项处理操作及测温任务的未知结果，再保存此项核查。此操作不自动控制设备。</p><label class="config-field">现场核查结论<textarea v-model="recoveryReason" required maxlength="1000" rows="3"></textarea></label><label class="checkbox"><input v-model="recoveryConfirmed" type="checkbox" required>已完成现场核查，确认当前配置及设备状态可以继续操作</label><button class="button" :disabled="busy||unsaved||!recoveryConfirmed||!recoveryReason.trim()">保存恢复核查结论</button><details><summary>旧网关结果不在恢复点中的处理</summary><p class="help">先核对并处置原浮子运动。仅清选定结果通道，执行中状态不允许清除；不推测旧动作，也不停止或重发动作。</p><label class="config-field">网关储罐<select v-model="recoveryTank" aria-label="恢复核查网关储罐"><option value="">请选择</option><option v-for="t in config?.tanks.filter(t=>config?.channels.find(c=>c.id===t.channelId)?.isGateway)" :key="t.id" :value="t.id">{{t.code}}</option></select></label><label class="config-field">结果通道<select v-model="recoveryCycle" aria-label="恢复核查结果通道"><option value="Normal">正常动作结果通道</option><option value="IndependentStop">独立停止结果通道</option></select></label><button type="button" class="button" :disabled="busy||unsaved||!recoveryTank||!recoveryConfirmed||!recoveryReason.trim()" @click="resetRecoveryGateway">仅复位所选网关结果通道</button></details></form><h2>业务数据备份</h2><p class="help">包含配置、账号、历史、事件及测温记录；不包含供方私钥和授权保护状态。恢复业务数据不会延长授权。</p><button v-if="can('BackupManage')" class="button" :disabled="busy||!licensed" @click="createBackup">创建业务备份</button><details class="storage-diagnostics"><summary>SQLite存储诊断</summary><pre>{{storage?JSON.stringify(storage,null,2):'当前身份无存储诊断权限'}}</pre></details><p>仪表操作按逐罐配置和账号权限开放，测温功能按协议和设备能力使用。</p></section></template>

 <template v-if="config&&view==='detail'"><div class="toolbar single-detail-toolbar"><div class="single-detail-title"><h1>单罐详情</h1><label class="config-field detail-selector"><span class="sr-only">选择储罐</span><select v-model="detailTank" aria-label="详情储罐"><option v-for="t in config.tanks.filter(t=>!t.hidden)" :key="t.id" :value="t.id">{{t.instrumentTag||t.code}} · {{t.code}} · {{t.medium||'介质未填'}}</option></select></label><span class="single-tank-name">{{config.tanks.find(t=>t.id===detailTank)?.name}}</span></div><div class="inline-actions"><button class="button" :disabled="!licensed||!can('DataExport')||!config.tanks.some(t=>t.id===detailTank&&!t.hidden)" @click="tankDetailScreen?.printDetail()">打印预览</button><button v-if="canConfigure&&config.tanks.find(t=>t.id===detailTank)" class="pin-button" :class="{pinned:!!config.tanks.find(t=>t.id===detailTank)?.pinnedAtUtc}" :disabled="busy||unsaved" @click="displayAction(config.tanks.find(t=>t.id===detailTank)!,config.tanks.find(t=>t.id===detailTank)!.pinnedAtUtc?'Unpin':'Pin')"><UiIcon name="pin"/>{{config.tanks.find(t=>t.id===detailTank)?.pinnedAtUtc?'取消置顶':'置顶'}}</button><button class="button" @click="choose('overview')">返回总览</button></div></div><TankDetail ref="tankDetailScreen" :licensed="licensed" v-if="config.tanks.find(t=>t.id===detailTank&&!t.hidden)" :key="detailTank" :config="config" :tank="config.tanks.find(t=>t.id===detailTank)!" :reading="reading(detailTank)" :valid="liveValid(reading(detailTank))" :admin="canConfigure" :can-operate="!!canOperate" :average-allowed="averageDelivered" :dirty="unsaved" :alarm-color="alarmColor(config.tanks.find(t=>t.id===detailTank)!)" :alarm-text="alarmText(config.tanks.find(t=>t.id===detailTank)!)" @updated="tablesUpdated" @edit="tankDraft=clone($event)" @trends="trendFocusTank=$event;choose('trends')" @average="averageFocusTank=$event;choose('wireless')"/><div v-else class="panel empty">暂无可显示的储罐；隐藏罐可在储罐配置中恢复显示。</div></template>
