 <div v-if="newIdentity" class="modal-backdrop"><section class="modal" role="dialog" aria-label="新增储罐标识"><div class="modal-head"><h2>新增储罐</h2><button class="button" @click="newIdentity=null">取消</button></div><form class="modal-body config-fields" @submit.prevent="confirmNewIdentity"><p class="help wide-field">先填写唯一仪表位号和罐号，再进入基本档案。</p><p v-if="identityError" class="error-message wide-field">{{identityError}}</p><label class="config-field">仪表位号 *<input v-model="newIdentity.tag" required maxlength="100" aria-label="新增仪表位号"></label><label class="config-field">罐号 *<input v-model="newIdentity.code" required maxlength="80" aria-label="新增罐号"></label><button class="button primary wide-field">下一步：填写基本档案</button></form></section></div>
 <div v-if="channelDraft||tankDraft||details" class="modal-backdrop"><section class="modal" role="dialog"><div class="modal-head"><h2>{{channelDraft?'采集通道':tankDraft?'基本档案':'事件明细'}}<small v-if="tankDraft" class="editor-identity">位号：{{tankDraft.instrumentTag||'未填写'}}　罐号：{{tankDraft.code||'未填写'}}</small></h2><button class="button" @click="channelDraft=null;tankDraft=null;details=null">关闭</button></div><div class="modal-body"><p v-if="tankDraft ? tankEditorError : error" role="alert" class="error-message">{{tankDraft ? tankEditorError : error}}</p>
 <form v-if="channelDraft" class="config-fields" @submit.prevent="acceptChannel"><label class="config-field">通道名称<input v-model="channelDraft.name" required maxlength="100"></label><label class="config-field">协议<select v-model="channelDraft.protocol" @change="channelProtocol"><option v-for="(name,key) in protocolNames" :key="key" :value="key">{{name}}</option></select></label><template v-if="channelDraft.protocol==='GatewayTcp'"><label class="config-field">网关IP<input v-model="channelDraft.host" required></label><label class="config-field">TCP端口<input v-model.number="channelDraft.tcpPort" type="number" min="1" max="65535" required></label></template><template v-else><label class="config-field">采集主机串口<select v-model="channelDraft.portName" required aria-label="采集主机串口"><option disabled value="">请选择采集主机串口</option><option v-for="port in serialPortChoices" :key="port" :value="port">{{port}}{{serialPorts.includes(port)?'':'（当前配置，未检测到）'}}</option></select><button type="button" class="text-button" :disabled="serialPortBusy" @click="loadSerialPorts">刷新串口列表</button><small class="help">请选择运行后台的电脑上的实际串口；刷新不打开或占用串口。</small><small v-if="serialPortError" class="error-message">{{serialPortError}}</small><small v-else-if="!serialPortBusy&&!serialPorts.length" class="help">未检测到可用串口，请检查串口设备或驱动后刷新列表。</small></label><label class="config-field">波特率<input v-model.number="channelDraft.baudRate" type="number" required></label><label class="config-field">校验<select v-model="channelDraft.parity"><option value="None">无</option><option value="Even">偶</option><option value="Odd">奇</option></select></label><label class="config-field">停止位<select v-model.number="channelDraft.stopBits"><option :value="1">1</option><option :value="2">2</option></select></label></template><label class="config-field">站号 / Unit ID<input v-model.number="channelDraft.unitId" type="number" min="1" max="247" required></label><label class="config-field">轮询间隔（ms）<input v-model.number="channelDraft.pollIntervalMs" type="number" min="500" max="60000" required></label><label class="config-field">读取超时（ms）<input v-model.number="channelDraft.readTimeoutMs" type="number" min="100" max="30000" required></label><label class="checkbox"><input v-model="channelDraft.enabled" type="checkbox">启用通道</label><div class="wide-field"><button class="button primary">应用到待保存配置</button></div></form>
 <form v-if="tankDraft" class="tank-editor-form" novalidate @input="tankEditorError=''" @submit.prevent="submitTank"><div class="tabs tank-editor-tabs" role="tablist" aria-label="储罐配置页签"><button v-for="[key,label] in tankTabs" :key="key" type="button" role="tab" :aria-selected="tankTab===key" :class="{active:tankTab===key}" @click="tankTab=key">{{label}}</button></div>
<section v-show="tankTab==='archive'" class="config-fields tank-editor-pane" data-tank-tab="archive" role="tabpanel" :aria-label="tankTabs.find(t=>t[0]==='archive')![1]"><div class="form-section-title wide-field"><b>01</b><div><h3>仪表档案</h3><p>标识、分组及尺寸。</p></div></div><label class="config-field">仪表位号 *<input v-model="tankDraft.instrumentTag" required maxlength="100" aria-label="仪表位号"></label><label class="config-field">罐号 *<input v-model="tankDraft.code" required maxlength="80" aria-label="罐号"></label><label class="config-field">名称（选填）<input v-model="tankDraft.name" maxlength="100" aria-label="储罐名称"></label>
<label class="config-field">产品编号（选填）<input v-model="tankDraft.productNumber" maxlength="100" aria-label="产品编号"></label>
<label class="config-field">所属罐区<input v-model="tankDraft.zone" maxlength="100" aria-label="罐区"></label>
<label class="config-field">介质<select v-model="tankDraft.mediumId" aria-label="关联介质" @change="tankDraft.medium=config?.media.find(m=>m.id===tankDraft?.mediumId)?.name||''"><option :value="null">未关联 / 手填名称</option><option v-for="m in config?.media" :key="m.id" :value="m.id">{{m.code}} · {{m.name}}</option></select><input v-if="!tankDraft.mediumId" v-model="tankDraft.medium" maxlength="100" aria-label="介质名称" placeholder="可填写介质名称"></label>
<label class="config-field">储罐类型<select v-model="tankDraft.shape" aria-label="罐型"><option v-for="(name,key) in shapeNames" :key="key" :value="key">{{name}}</option></select></label>
<label class="config-field">设备批次（选填）<input v-model="tankDraft.batch" maxlength="100" aria-label="设备批次"></label>
<label class="config-field">罐高 / 量程 mm<input v-model.number="tankDraft.heightMm" type="number" min="1" max="100000" required aria-label="罐高（mm）"></label>
<label class="config-field">罐径 mm（选填）<input :value="tankDraft.diameterMm??''" type="number" min="0.001" max="1000000" step="any" aria-label="罐径 mm" @input="archiveNumber('diameterMm',$event)"></label>
<label class="config-field">公称容量 m³（选填）<input :value="tankDraft.nominalCapacityM3??''" type="number" min="0.001" max="1000000000" step="any" aria-label="公称容量 m³" @input="archiveNumber('nominalCapacityM3',$event)"></label>
<div class="config-field"><span>所属罐组（可多选）</span><details class="tank-group-picker"><summary>{{tankGroupIds.length?config?.groups.filter(g=>tankGroupIds.includes(g.id)).map(g=>g.name).join('、'):'暂不分配'}}</summary><div class="tank-group-options"><label v-for="g in config?.groups" :key="g.id" class="checkbox"><input v-model="tankGroupIds" type="checkbox" :value="g.id" :aria-label="'所属罐组 '+g.name">{{g.name}}<small>{{groupKindNames[g.kind]}}</small></label><p v-if="!config?.groups.length" class="help">可先在“罐组管理”中增加分组。</p></div></details></div>
<p class="help wide-field">罐径、公称容量为档案资料；体积仍按已关联并启用的罐容表计算，不按外形估算。</p>
<label class="checkbox wide-field"><input v-model="tankDraft.hidden" type="checkbox">在总览与详情隐藏（仍采集、报警、保存历史）</label></section>
<section v-show="tankTab==='binding'" class="config-fields tank-editor-pane" data-tank-tab="binding" role="tabpanel" :aria-label="tankTabs.find(t=>t[0]==='binding')![1]"><div class="form-section-title wide-field"><b>02</b><div><h3>通讯绑定</h3><p>协议、采集通道与设备编号。</p></div></div><label class="config-field">采用协议<select v-model="tankProtocol" aria-label="采用协议" @change="changeTankProtocol"><option v-for="(name,key) in protocolNames" :key="key" :value="key">{{name}}</option></select></label>
<label class="config-field">绑定采集通道<select v-model="tankDraft.channelId" required aria-label="采集通道"><option value="" disabled>请选择匹配协议的采集通道</option><option v-for="c in tankChannels" :key="c.id" :value="c.id">{{c.name}}</option></select></label>
<label class="config-field" :title="tankProtocol.startsWith('Gateway')?'填写网关仪表列表左侧的槽位号，不是液位计通讯地址。':undefined">{{draftAddressLabel}}<input v-model.number="draftTableAddress" type="number" :min="tankProtocol==='IfxL25'?32*((draftChannel?.unitId||1)-1):1" :max="tankProtocol==='IfxL25'?32*(draftChannel?.unitId||1)-1:tankProtocol.startsWith('Gateway')?64:243" required :aria-label="draftAddressLabel"></label>
<label class="config-field">采集启用状态<select v-model="tankDraft.enabled" aria-label="采集启用状态"><option :value="true">启用</option><option :value="false">停用</option></select></label>
<div class="wide-field editor-section binding-summary"><template v-if="draftChannel"><strong>{{draftChannel.name}} · {{protocolNames[draftChannel.protocol]}}</strong><p>{{draftChannel.protocol==='GatewayTcp'?draftChannel.host+':'+draftChannel.tcpPort:draftChannel.portName}}<template v-if="draftChannel.protocol!=='DirectRtu'"> · 站号 / Unit ID {{draftChannel.unitId}}</template><template v-else> · 本罐仪表站号 {{tankDraft.address}}</template></p><p v-if="draftChannel.protocol==='IfxL25'">一个COM口、一个站号可读取32台；表地址范围 {{32*((draftChannel.unitId||1)-1)}}～{{32*(draftChannel.unitId||1)-1}}，本罐对应内部序号 {{tankDraft.address}}。</p><p v-else-if="draftChannel.protocol.startsWith('Gateway')">一个网关最多64台，每个南向COM支持16通道；本罐编号按网关交付对应表配置。</p><p v-else>每条RS-485线路最多32台，仪表站号按实际接线配置。</p></template><p v-else>请绑定采用所选协议的采集通道；如无匹配通道，先在“通讯通道”中新增。</p></div>
<p class="help wide-field">串口及网络连接参数在“通讯通道”统一维护，同一物理线路共用参数。</p></section>
<section v-show="tankTab==='alarm'" class="config-fields tank-editor-pane" data-tank-tab="alarm" role="tabpanel" :aria-label="tankTabs.find(t=>t[0]==='alarm')![1]"><div class="form-section-title wide-field"><b>06</b><div><h3>报警配置</h3><p>四限、回差、延时与设备故障监测。</p></div></div><AlarmEditor :settings="tankDraft.alarms"/></section>
<section v-show="tankTab==='meter'" class="config-fields tank-editor-pane" data-tank-tab="meter" role="tabpanel" :aria-label="tankTabs.find(t=>t[0]==='meter')![1]"><div class="form-section-title wide-field"><b>04</b><div><h3>计量参数</h3><p>按计算密度、扣水与参考资料、压力输入分别配置。</p></div></div>
<div class="wide-field editor-section meter-density-group"><h3>计算密度</h3><div class="config-fields"><label class="config-field">计算密度来源<select v-model="tankDraft.metering.densitySource" aria-label="计算密度来源"><option value="Instrument">仪表实测密度</option><option value="Manual">人工工况密度</option></select></label><label class="config-field">人工工况密度 kg/m³<input :value="tankDraft.metering.manualOperatingDensityKgM3??''" aria-label="人工工况密度" type="number" step="any" min="0.001" max="1000000" @input="tankDraft!.metering.manualOperatingDensityKgM3=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null"></label><label class="checkbox wide-field"><input v-model="tankDraft.metering.showInstrumentDensity" type="checkbox">显示仪表实测密度（仍采集并保存历史）</label></div><p class="help">质量和静压力修正采用所选来源；人工工况密度可独立填写，切换来源不会清除原值。</p></div>
<div class="wide-field editor-section meter-reference-group"><h3>扣水与参考资料</h3><div class="config-fields"><label class="config-field">水位 mm<input :value="tankDraft.metering.waterHeightMm??''" @input="tankDraft!.metering.waterHeightMm=($event.target as HTMLInputElement).value===''?null:Number(($event.target as HTMLInputElement).value)" type="number" step="0.1" min="0" :max="tankDraft.heightMm" placeholder="输入水层高度"><small v-if="tankDraft.metering.waterHeightMm==null">未填写时沿用旧人工水体积 {{tankDraft.metering.waterVolumeM3}} m³</small><small>按主表或主表＋小数表计算水体积；不重复叠加整体静压力修正。</small></label>
<label class="config-field">20℃标准密度 kg/m³（可空）<input :value="tankDraft.metering.standardDensity20KgM3??''" type="number" step="any" min="0.001" @input="tankDraft!.metering.standardDensity20KgM3=($event.target as HTMLInputElement).value?Number(($event.target as HTMLInputElement).value):null"></label>
</div><p class="help">人工水体积用于扣水。20℃标准密度独立保留，不代替所选工况密度。</p></div>
<div class="wide-field editor-section"><h3>4～20mA压力输入</h3><p class="help">≤3.2mA按断线处理；3.2～4mA显示下限，超过20mA显示上限。<template v-if="tankProtocol==='IfxL25'">IFX30000 不提供压力数据，两路压力输入均已关闭。</template></p><div v-for="(p,i) in [tankDraft.pressure1,tankDraft.pressure2]" :key="i" class="pressure-settings"><label class="checkbox"><input v-model="p.enabled" type="checkbox" :disabled="tankProtocol==='IfxL25'">启用压力输入{{i+1}}</label><div v-if="p.enabled" class="config-fields"><label class="config-field">4mA对应工程量<input v-model.number="p.at4Ma" type="number" step="any" required></label><label class="config-field">20mA对应工程量<input v-model.number="p.at20Ma" type="number" step="any" required></label><label class="config-field">压力单位<select v-model="p.unit" :aria-label="'压力输入'+(i+1)+'单位'"><option value="KPa">kPa</option><option value="MPa">MPa</option><option value="Bar">bar</option></select></label></div></div></div><p class="help wide-field">净体积扣除人工水体积；质量与静压力修正使用所选工况密度；来源无效不自动替换。20℃标准密度独立保存。</p></section>
<section v-show="tankTab==='capacity'" class="config-fields tank-editor-pane" data-tank-tab="capacity" role="tabpanel" :aria-label="tankTabs.find(t=>t[0]==='capacity')![1]"><div class="form-section-title wide-field"><b>03</b><div><h3>关联罐容表</h3><p>分别选择已校核启用的表。</p></div></div><label class="checkbox"><input v-model="tankDraft.metering.enabled" type="checkbox">启用体积计算</label><label class="config-field">主罐容表<select v-model="tankDraft.metering.mainTableId" aria-label="主罐容表"><option :value="null">暂不关联</option><option v-for="t in capacitySummaries.filter(x=>x.kind==='Main'&&x.enabled)" :key="t.id" :value="t.id">{{t.number}} · {{t.name}}</option></select></label>
<label class="config-field">静压力容积修正表<select v-model="tankDraft.metering.staticPressureTableId" aria-label="静压力容积修正表"><option :value="null">暂不关联</option><option v-for="t in capacitySummaries.filter(x=>x.kind==='StaticPressure'&&x.enabled)" :key="t.id" :value="t.id">{{t.number}} · 参考密度 {{t.referenceDensityKgM3}} kg/m³</option></select></label>
<label class="config-field">小数表<select v-model="tankDraft.metering.decimalTableId" aria-label="小数表"><option :value="null">暂不关联</option><option v-for="t in capacitySummaries.filter(x=>x.kind==='Decimal'&&x.enabled)" :key="t.id" :value="t.id">{{t.number}} · {{t.name}}</option></select></label>
<label class="config-field">基础体积算法<select v-model="tankDraft.metering.baseVolumeMethod" aria-label="基础体积算法"><option value="Interpolate">主表插值（不叠加小数表）</option><option value="MainPlusDecimal">主表下节点＋小数表增量</option></select></label><p class="help wide-field">组合模式须关联五列分区小数表，不足1mm按相邻毫米线性插值。静压力修正＝表量×所选工况密度÷参考密度，主表与小数表不重复插值。</p></section>
<section v-show="tankTab==='control'" class="config-fields tank-editor-pane" data-tank-tab="control" role="tabpanel" :aria-label="tankTabs.find(t=>t[0]==='control')![1]"><div class="form-section-title wide-field"><b>05</b><div><h3>操作与温度</h3><p>按罐配置温度计类型和允许的操作。</p></div></div><label class="config-field">温度类型<select v-model="tankDraft.temperatureMode" aria-label="温度类型"><option v-for="(name,key) in tempNames" :key="key" :value="key">{{key==='Wireless'&&!averageDelivered?'仪表温度':name}}</option></select></label>
<label v-if="tankDraft.temperatureMode==='Ats'" class="config-field">温度计测点数<input v-model.number="tankDraft.atsPointCount" type="number" min="1" max="16" required></label>
<div v-if="tankDraft.temperatureMode==='Ats'" class="wide-field editor-section"><h3>温度计测点高度（可空，mm）</h3><div class="config-fields"><label v-for="i in tankDraft.atsPointCount" :key="i" class="config-field">第{{i}}点高度<input v-model.number="tankDraft.atsHeightsMm[i-1]" type="number" min="0" max="100000" step="any"></label></div><p class="help">高度用于显示位置；所有正常读取的配置测点均参与温度计平均温度，包括0℃和液面以上的正常测点。</p></div>
<ControlsEditor :settings="tankDraft.controls" :average-allowed="averageDelivered" :wireless="tankDraft.temperatureMode==='Wireless'" :ifx="tankProtocol==='IfxL25'"/><label class="config-field wide-field">备注（选填）<textarea v-model="tankDraft.notes" maxlength="1000" rows="3" aria-label="储罐备注"></textarea></label></section>
<div class="tank-editor-footer"><span class="help">先应用到待保存配置，再点击页面“保存配置”统一生效。</span><div class="tank-editor-footer-actions"><button type="button" class="button" @click="tankDraft=null">取消</button><button type="submit" class="button primary">应用到待保存配置</button></div></div></form>
 <pre v-if="details" class="event-details">{{details.details}}</pre></div></section></div>
 </template>
</template>
